"use strict";
import UniswapXRouterLabel from "components/RouterLabel/UniswapXRouterLabel";
import { QuoteMethod } from "state/routing/types";
import { isUniswapXTrade } from "state/routing/utils";
import { ThemedText } from "theme/components";
export default function RouterLabel({ trade, color }) {
  if (isUniswapXTrade(trade)) {
    return <UniswapXRouterLabel>
        <ThemedText.BodySmall>Aborean X</ThemedText.BodySmall>
      </UniswapXRouterLabel>;
  }
  if (trade.quoteMethod === QuoteMethod.CLIENT_SIDE_FALLBACK) {
    return <ThemedText.BodySmall color={color}>Aborean Client</ThemedText.BodySmall>;
  }
  return <ThemedText.BodySmall color={color}>Aborean API</ThemedText.BodySmall>;
}
