import { useMemo, useRef } from 'react'
import { AccountMeta } from 'uniswap/src/features/accounts/types'
import { useTransactionGasFee } from 'uniswap/src/features/gas/hooks'
import { isAbstractChain } from 'uniswap/src/constants/abstractContracts'
import { useWrapTransactionRequest } from 'uniswap/src/features/transactions/swap/contexts/hooks/useWrapTransactionRequest'
import { WRAP_FALLBACK_GAS_LIMIT_IN_GWEI } from 'uniswap/src/features/transactions/swap/review/services/swapTxAndGasInfoService/constants'
import {
  TransactionRequestInfo,
  getIsWrapApplicable,
  processWrapResponse,
} from 'uniswap/src/features/transactions/swap/review/services/swapTxAndGasInfoService/utils'
import { DerivedSwapInfo } from 'uniswap/src/features/transactions/swap/types/derivedSwapInfo'
import { TokenApprovalInfo } from 'uniswap/src/features/transactions/swap/types/trade'
import { getTradeSettingsDeadline } from 'uniswap/src/data/apiClients/tradingApi/utils/getTradeSettingsDeadline'
import { useTransactionSettingsContext } from 'uniswap/src/features/transactions/settings/contexts/TransactionSettingsContext'
import { AbstractSwapRouter } from '../../services/AbstractSwapRouter'

export function useWrapTransactionRequestInfo({
  derivedSwapInfo,
  account,
}: {
  derivedSwapInfo: DerivedSwapInfo
  account?: AccountMeta
}): TransactionRequestInfo {
  const wrapTxRequest = useWrapTransactionRequest(derivedSwapInfo, account)
  const gasFeeResult = useTransactionGasFee(
    wrapTxRequest,
    !getIsWrapApplicable({ derivedSwapInfo }),
    undefined,
    WRAP_FALLBACK_GAS_LIMIT_IN_GWEI * 10e9,
  ) // Skip Gas Fee API call on transactions that don't need wrapping

  const result = useMemo(() => processWrapResponse({ gasFeeResult, wrapTxRequest }), [gasFeeResult, wrapTxRequest])

  const cachedGasFeeResultRef = useRef(gasFeeResult)
  if (gasFeeResult.value) {
    cachedGasFeeResultRef.current = gasFeeResult
  }

  // Wrap gas cost should not change significantly between trades, so we can use the last value if current is unavailable.
  const resultWithCaching = useMemo(() => {
    const value = result.gasFeeResult.value ?? cachedGasFeeResultRef.current.value
    const displayValue = result.gasFeeResult.displayValue ?? cachedGasFeeResultRef.current.displayValue

    const gasFeeResultWithCaching = {
      ...result.gasFeeResult,
      value,
      displayValue,
    }

    return { ...result, gasFeeResult: gasFeeResultWithCaching }
  }, [result])

  return resultWithCaching
}

// Abstract DEX transaction request info hook
function useAbstractTransactionRequestInfo({
  derivedSwapInfo,
  account,
}: {
  derivedSwapInfo: DerivedSwapInfo
  account?: AccountMeta
}): TransactionRequestInfo {
  const { customDeadline, customSlippageTolerance, autoSlippageTolerance } = useTransactionSettingsContext()
  
  // Initialize our clean service architecture
  const swapRouter = useMemo(() => new AbstractSwapRouter(), [])

  const mockTxRequest = useMemo(() => {
    const { trade, chainId, currencyAmounts } = derivedSwapInfo
    
    if (!account?.address || !isAbstractChain(chainId) || !trade.trade) {
      return undefined
    }

    // Get user settings
    const deadline = getTradeSettingsDeadline(customDeadline) || (Math.floor(Date.now() / 1000) + 1800)
    const slippageValue = customSlippageTolerance || autoSlippageTolerance || 0.5
    const slippageTolerance = Math.floor(slippageValue * 100) // Convert to basis points

    // Use our clean service architecture instead of the monolithic mess!
    return swapRouter.buildSwapTransaction({
      trade,
      currencyAmounts,
      chainId,
      account,
      slippageTolerance,
      deadline
    })
  }, [derivedSwapInfo, account, customDeadline, customSlippageTolerance, autoSlippageTolerance, swapRouter])

  // Use Abstract DEX gas estimation instead of Uniswap API
  const gasFeeResult = useMemo(() => {
    if (!mockTxRequest || !isAbstractChain(derivedSwapInfo.chainId)) {
      return {
        value: undefined,
        displayValue: undefined,
        error: null,
        isLoading: false,
        gasEstimates: undefined,
      }
    }

    // Hardcoded gas estimation for Abstract DEX - 1 gwei
    const gasLimitEstimate = 200000 // Gas units for V2 swap
    const gasPrice = 1000000000 // 1 gwei in wei (hardcoded)
    const gasFeeWei = (gasLimitEstimate * gasPrice).toString()
    const gasFeeUSD = 0.2 // Hardcoded to $0.20 USD

    return {
      value: gasFeeWei,
      displayValue: gasFeeWei,
      error: null,
      isLoading: false,
      gasEstimates: {
        activeEstimate: {
          strategy: 'standard' as const,
          gasLimit: gasLimitEstimate.toString(),
          gasFee: gasFeeWei,
          gasCostUSD: gasFeeUSD.toString(),
        },
        shadowEstimates: [],
      },
    }
  }, [mockTxRequest, derivedSwapInfo.chainId])

  return useMemo(() => {
    const gasEstimate = {
      swapEstimates: gasFeeResult.gasEstimates || [{
        strategy: 'standard' as const,
        gasLimit: '200000',
        gasCostUSD: '0.20',
      }],
    }

    return {
      gasFeeResult,
      txRequests: mockTxRequest ? [mockTxRequest] : undefined,
      gasEstimate,
      swapRequestArgs: undefined,
    }
  }, [gasFeeResult, mockTxRequest])
}

export function useTransactionRequestInfo({
  derivedSwapInfo,
  tokenApprovalInfo,
  account,
}: {
  derivedSwapInfo: DerivedSwapInfo
  tokenApprovalInfo: TokenApprovalInfo | undefined
  account?: AccountMeta
}): TransactionRequestInfo {
  const wrapTransactionRequestInfo = useWrapTransactionRequestInfo({
    derivedSwapInfo,
    account,
  })

  const abstractTransactionRequestInfo = useAbstractTransactionRequestInfo({
    derivedSwapInfo,
    account
  })

  const isWrapApplicable = getIsWrapApplicable({ derivedSwapInfo })


  // Handle wrapping (ETH <-> WETH)
  if (isWrapApplicable) {
    return wrapTransactionRequestInfo
  }

  // All other trades go through Abstract DEX
  return abstractTransactionRequestInfo
}
